const rows = $input.first().json.data || [];
const byWf = {};
for (const r of rows) {
  if (r.workflowId === 'Aul2pyDbdIECaBhY') continue;
  if (r.mode === 'manual') continue;
  if (r.workflowData && r.workflowData.active === false) continue;
  if (!(r.data && r.data.resultData && r.data.resultData.error && r.data.resultData.error.message)) continue;
  const name = (r.workflowData && r.workflowData.name) || r.workflowId || 'desconocido';
  if (!byWf[name]) byWf[name] = { count: 0, lastErr: null, lastAt: null };
  byWf[name].count += 1;
  const at = r.stoppedAt || r.startedAt || null;
  if (!byWf[name].lastAt || (at && at > byWf[name].lastAt)) {
    byWf[name].lastAt = at;
    byWf[name].lastErr = r.data.resultData.error.message || '';
  }
}
const out = [];
for (const name of Object.keys(byWf)) {
  const g = byWf[name];
  if (g.count < 2) continue;
  const safeName = sanitize(name);
  const safeErr = sanitize(g.lastErr) || "sin mensaje";
  const signalKey = 'n8n_exec_fail:' + safeName;
  const titulo = safeName + " falló " + g.count + " veces: " + safeErr;
  out.push({ json: {
    senal: 'n8n_exec_fail',
    fuente: safeName,
    signalKey: signalKey,
    titulo: titulo.slice(0, 200),
    descripcion: 'Senal automatica (Sentinela v1): el workflow n8n **' + safeName + '** registro ' + g.count + ' ejecuciones con estado error en las ultimas 100 ejecuciones.\n\nUltimo error (sanitizado): ' + safeErr + '\n\nNivel de autonomia: pr-only (maximo).\n\nsignal-key: ' + signalKey,
  } });
}
return out;

function sanitize(s) {
