function median(arr) {
  if (!arr.length) return 0;
  const a = arr.slice().sort(function (x, y) { return x - y; });
  const mid = Math.floor(a.length / 2);
  return a.length % 2 ? a[mid] : (a[mid - 1] + a[mid]) / 2;
}
function dayNum(isoDate) { return Math.round(DateTime.fromISO(isoDate).toMillis() / 86400000); }
const rows = $input.all().map(function (i) { return i.json; });
const hoyCOT = $now.setZone('America/Bogota').toISODate();
const byFuente = {};
for (const r of rows) {
  const fuente = (r.entidad || '') + '|' + (r.evento || '');
  const diaCOT = r.created_at ? DateTime.fromISO(r.created_at, { zone: 'utc' }).setZone('America/Bogota').toISODate() : null;
  if (!diaCOT) continue;
  if (!byFuente[fuente]) byFuente[fuente] = { entidad: r.entidad, evento: r.evento, dias: new Set() };
  byFuente[fuente].dias.add(diaCOT);
}
const out = [];
for (const fuente of Object.keys(byFuente)) {
  const info = byFuente[fuente];
  const dias = Array.from(info.dias).sort();
  if (dias.length < 2) continue;
  if (dias.indexOf(hoyCOT) !== -1) continue;
  const nums = dias.map(dayNum);
  const intervals = [];
  for (let k = 1; k < nums.length; k++) intervals.push(nums[k] - nums[k - 1]);
  let med = median(intervals);
  if (med < 1) med = 1;
  const ultima = dias[dias.length - 1];
  const desdeUltima = dayNum(hoyCOT) - dayNum(ultima);
  if (desdeUltima <= 2 * med) continue;
  const safeEnt = sanitize(info.entidad);
  const safeEv = sanitize(info.evento);
  const etiqueta = safeEnt + (safeEv ? " / " + safeEv : "");
  const signalKey = 'sync_gap:' + etiqueta;
  out.push({ json: {
    senal: 'sync_gap',
    fuente: etiqueta,
    signalKey: signalKey,
    titulo: ("Sync " + etiqueta + " no corrió hoy").slice(0, 200),
    descripcion: 'Senal automatica (Sentinela v1): la fuente **' + etiqueta + '** lleva ' + desdeUltima + ' dias sin registrar filas en sync_log (mediana de su cadencia: ' + med + ' dias, umbral 2x). Hoy: ' + hoyCOT + ' (zona America/Bogota). Ultima corrida: ' + ultima + '.\n\nNivel de autonomia: pr-only (maximo).\n\nsignal-key: ' + signalKey,
  } });
}
return out;

function sanitize(s) {
